[Fact]
public void AcceptsValidPayload()
{
    var result = CreateUserEndpoint.HandleJson("{\"email\":\"a@b.co\",\"name\":\"Ada\",\"age\":30}");

    var created = Assert.IsType<Created<CreateUserRequest>>(result);
    Assert.Equal(StatusCodes.Status201Created, created.StatusCode);
    Assert.Equal("Ada", created.Value?.Name);
}

/// <summary>Verifies that a missing payload returns a problem response.</summary>
[Fact]
public void RejectsMissingPayload()
{
    var result = CreateUserEndpoint.HandleJson(null);

    var problem = Assert.IsType<ProblemHttpResult>(result);
    Assert.Equal(StatusCodes.Status400BadRequest, problem.StatusCode);
    Assert.Equal(StatusCodes.Status400BadRequest, problem.ProblemDetails.Status);
    Assert.Contains("required", problem.ProblemDetails.Detail);
}

/// <summary>Verifies that a payload with missing fields returns a problem response.</summary>
[Fact]
public void RejectsMissingFields()
{
    var result = CreateUserEndpoint.HandleJson("{\"name\":\"Ada\"}");

    var problem = Assert.IsType<ProblemHttpResult>(result);
    Assert.Equal(StatusCodes.Status400BadRequest, problem.StatusCode);
    Assert.Contains("email", problem.ProblemDetails.Detail);
}

/// <summary>Verifies that a malformed payload returns a problem response.</summary>
[Fact]
public void RejectsMalformedPayload()
{
    var result = CreateUserEndpoint.HandleJson("{\"email\":");

    var problem = Assert.IsType<ProblemHttpResult>(result);
    Assert.Equal(StatusCodes.Status400BadRequest, problem.StatusCode);
    Assert.Contains("JSON", problem.ProblemDetails.Detail);
}

/// <summary>Verifies that malformed field values return a problem response.</summary>
